import{obterJSON,endereco,consultaLimpa,pontuarCorrespondencia,idiomas}from'./comum.js';
const lista=v=>Array.isArray(v)?v:v==null?[]:[v];
export function converterDoaj(item){const b=item?.bibjson||{},id=String(item?.id||'').trim();if(!id)return null;const titulo=String(b.title||'Sem título'),autores=lista(b.author).map(a=>typeof a==='string'?a:a?.name).filter(Boolean).map(String),links=lista(b.link),full=links.find(x=>String(x?.type||'').toLowerCase()==='fulltext')||links.find(x=>x?.url),doi=lista(b.identifier).find(x=>String(x?.type||'').toLowerCase()==='doi')?.id,pagina=endereco(`https://doaj.org/article/${id}`),ler=endereco(full?.url)||pagina;if(!ler)return null;const pdf=endereco(full?.url)&&(/pdf/i.test(String(full?.content_type||''))||/\.pdf(?:$|\?)/i.test(String(full?.url||'')))?endereco(full.url):null,descricao=[b.abstract,b.journal?.title,b.year].filter(Boolean).join(' · ');return{id:`doaj:${id}`,fonte:'doaj',provedor:'DOAJ · Directory of Open Access Journals',titulo,autores,idiomas:idiomas(b.journal?.language||[]),capa:null,descricao,acessoLivre:true,dominioPublico:false,tipoAcesso:'Artigo científico · acesso aberto',licenca:'O DOAJ indexa periódicos e artigos de acesso aberto. A licença específica do artigo é indicada no registro ou no site da publicação.',origem:pagina||ler,ler,texto:null,formatos:pdf?[{tipo:'PDF',url:pdf}]:[],doi:doi||null}}
export async function pesquisarDoaj(q,o={}){const termo=consultaLimpa(q);if(!termo)return{livros:[],total:0,temMais:false};const pagina=Math.max(1,o.pagina||1),u=new URL('/api/acervos-gratuitos',location.origin);u.searchParams.set('fonte','doaj');u.searchParams.set('q',termo);u.searchParams.set('pagina',String(pagina));const d=await obterJSON(u,15000,3),itens=Array.isArray(d?.results)?d.results:[],livros=itens.map(converterDoaj).filter(Boolean);for(const l of livros)l.relevancia=pontuarCorrespondencia(termo,l.titulo,l.autores);livros.sort((a,b)=>(b.relevancia||0)-(a.relevancia||0));const total=Number(d?.total)||livros.length;return{livros,total,temMais:pagina*20<total&&itens.length>0}}
